"use client";
/* Star, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Star(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("star"); }, []);
  return React.createElement("piix-sprite", { "name": "star", ...piixAttrs(props) });
}

export default Star;
